let S, TH;

function setup() {
	createCanvas(windowWidth, windowHeight);
	S = max(width, height);
	loop();
}

function draw() {
	blendMode(BLEND)
	background("tan");

	translate(width/2, height/2);
	rotate(random(TAU))
	TH = random(10, 30);

	strokeWeight(TH * 0.95);
	stroke("darkred");
	drawSpiralSquircle(S * 0.9, TH * 1.5);

	blendMode(MULTIPLY);
	rotate(random(-0.2, 0.2))
	stroke("steelblue");
	drawSpiralSquircle(S * 0.9 - TH * 2, TH * 1.5, random(-0.3, 0.3));

	// noLoop() removed for animation
}

function mousePressed() {
	if (mouseButton.left) redraw();
}

function drawSpiralSquircle(size, step, a = 0, exponent = 3) {
  noFill();
  beginShape();

  // let a = 0;          // angle
  let r = size / 2;   // radius (decreases each loop)

  while (r > step) {
    // superellipse / squircle formula
    let ca = cos(a);
    let sa = sin(a);

    let x = Math.sign(ca) * pow(abs(ca), 2/exponent) * r;
    let y = Math.sign(sa) * pow(abs(sa), 2/exponent) * r;

    vertex(x, y);

    a += 0.12;      // smaller step = smoother spiral
    r -= step/40;   // reduce radius
  }

  endShape();
}

function AdrawSpiralRect(sze, d, mn = d) {
	noFill();
	beginShape();
	let a = 0;
	while (sze > d) {
		var x = cos(a) * sze * 0.5;
		var y = sin(a) * sze * 0.5;
		vertex(x, y);
		sze -= d/4;
		a += HALF_PI;
	}
	endShape();
}
